import React, { useEffect, useState } from 'react';
import { Loader2, ShieldCheck, AlertTriangle, MessageSquareOff, MapPin, Search } from 'lucide-react';
import { TargetType } from '../types.ts';

interface LoadingScreenProps {
  phase: 'protocol' | 'analysis';
  targetType: TargetType;
  targetName: string;
}

const LoadingScreen: React.FC<LoadingScreenProps> = ({ phase, targetType, targetName }) => {
  const [status, setStatus] = useState('Iniciando conexão segura...');

  const protocolStages = [
    'Conectando ao firewall do servidor...',
    'Bypassing criptografia end-to-end...',
    'Sincronizando banco de dados local...',
    'Aguardando resposta do protocolo SSL...',
    'Garantindo anonimato da conexão...'
  ];

  const analysisStages = [
    { text: 'mensagens apagadas detectadas', color: 'text-red-500', icon: MessageSquareOff },
    { text: 'conversas suspeitas encontradas', color: 'text-red-500', icon: AlertTriangle },
    { text: 'rastreador de localização ativo', color: 'text-green-500', icon: MapPin },
    { 
      text: targetType === 'wife' ? 'elogios de outros homens detectados' : 'mensagens elogiando outras mulheres', 
      color: 'text-red-500', 
      icon: Search 
    }
  ];

  const [visibleAnalysis, setVisibleAnalysis] = useState<number[]>([]);

  useEffect(() => {
    if (phase === 'protocol') {
      let currentIdx = 0;
      const interval = setInterval(() => {
        if (currentIdx < protocolStages.length) {
          setStatus(protocolStages[currentIdx]);
          currentIdx++;
        }
      }, 600);
      return () => clearInterval(interval);
    } else {
      analysisStages.forEach((_, idx) => {
        setTimeout(() => {
          setVisibleAnalysis(prev => [...prev, idx]);
        }, (idx + 1) * 700);
      });
    }
  }, [phase]);

  return (
    <div className="w-full max-w-md bg-white rounded-3xl p-8 shadow-2xl animate-fade-in flex flex-col items-center">
      {phase === 'protocol' ? (
        <>
          <div className="relative mb-10">
            <div className="absolute inset-0 bg-[#2CA884]/20 rounded-full animate-ping"></div>
            <div className="relative w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center border-2 border-[#2CA884]">
              <Loader2 className="text-[#2CA884] animate-spin" size={48} />
            </div>
          </div>

          <div className="text-center w-full">
            <h3 className="text-lg font-bold text-gray-800 mb-6 uppercase tracking-widest font-tech">Processando Protocolos</h3>
            <div className="space-y-4 mb-8">
              <div className="flex items-center gap-4 bg-gray-50 p-4 rounded-xl border border-gray-100">
                 <ShieldCheck size={20} className="text-[#2CA884]" />
                 <div className="flex-1 h-1 bg-gray-200 rounded-full overflow-hidden">
                    <div className="w-full h-full bg-[#2CA884] origin-left"></div>
                 </div>
              </div>
            </div>
            <p className="text-sm font-semibold text-[#2CA884] animate-pulse">
              {status}
            </p>
          </div>
        </>
      ) : (
        <div className="w-full animate-fade-in">
          <div className="flex items-center justify-center mb-6">
            <div className="w-16 h-16 bg-red-50 rounded-full flex items-center justify-center border-2 border-red-500 animate-pulse">
              <AlertTriangle className="text-red-500" size={32} />
            </div>
          </div>
          <h3 className="text-center text-lg font-bold text-gray-800 mb-6 uppercase tracking-widest font-tech">
            Analisando Integridade de {targetName}
          </h3>
          <div className="space-y-3">
            {analysisStages.map((stage, idx) => (
              <div 
                key={idx}
                className={`flex items-center gap-3 p-4 rounded-xl border border-gray-100 transition-all duration-500 transform ${visibleAnalysis.includes(idx) ? 'opacity-100 translate-y-0 bg-gray-50' : 'opacity-0 translate-y-4'}`}
              >
                <stage.icon size={18} className={stage.color} />
                <span className={`text-xs font-bold uppercase tracking-wide ${stage.color}`}>{stage.text}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default LoadingScreen;

import React, { useState } from 'react';
import Header from './components/Header.tsx';
import Footer from './components/Footer.tsx';
import StepSelection from './components/StepSelection.tsx';
import StepDataEntry from './components/StepDataEntry.tsx';
import LoadingScreen from './components/LoadingScreen.tsx';
import StepProfileFound from './components/StepProfileFound.tsx';
import VSLPage from './components/VSLPage.tsx';
import { AppStep, TargetType, FormData } from './types.ts';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.SELECTION);
  const [targetType, setTargetType] = useState<TargetType>(null);
  const [formData, setFormData] = useState<FormData>({ targetName: '', targetPhone: '' });
  const [profilePhoto, setProfilePhoto] = useState<string | null>(null);

  const handleTargetSelect = (target: TargetType) => {
    setTargetType(target);
    localStorage.setItem('sentinel_target_type', target || '');
    setStep(AppStep.DATA_ENTRY);
  };

  const handleDataSubmit = async (data: { name: string; phone: string }) => {
    setFormData({ targetName: data.name, targetPhone: data.phone });
    localStorage.setItem('sentinel_target_name', data.name);
    localStorage.setItem('sentinel_target_phone', data.phone);

    // 1. Inicia Protocolos
    setStep(AppStep.PROTOCOL);

    // 2. Faz o envio e tenta pegar a foto
    try {
      const response = await fetch('https://nen.auto-jornada.space/webhook/hook-sentinel-pro', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          tipoAlvo: targetType,
          nomeAlvo: data.name,
          telefoneAlvo: data.phone,
          dataHora: new Date().toLocaleString('pt-BR'),
          urlOrigem: window.location.href
        }),
      });

      if (response.ok) {
        const result = await response.json();
        // O n8n deve retornar algo como { "photoUrl": "..." }
        if (result && result.photoUrl) {
          setProfilePhoto(result.photoUrl);
        }
      }
    } catch (error) {
      console.error('Erro ao processar webhook:', error);
    }

    // Fluxo de Transição:
    // Protocolo (3s) -> Perfil Encontrado (4s) -> Análise (4s) -> VSL

    setTimeout(() => {
      setStep(AppStep.PROFILE_FOUND);

      setTimeout(() => {
        setStep(AppStep.ANALYSIS);

        setTimeout(() => {
          setStep(AppStep.VSL);
        }, 4500);
      }, 4500);
    }, 3500);
  };

  const isDarkStep = step === AppStep.VSL || step === AppStep.PROTOCOL || step === AppStep.ANALYSIS;

  return (
    <div className={`min-h-screen flex flex-col items-center selection:bg-[#2CA884]/30 transition-colors duration-1000 ${isDarkStep ? 'bg-[#120a0a]' : 'bg-gradient-to-b from-[#1a1a1a] to-[#2d2d2d]'}`}>
      {step !== AppStep.VSL && <Header />}

      <main className="flex-1 w-full flex items-center justify-center p-4">
        {step === AppStep.SELECTION && (
          <StepSelection onSelect={handleTargetSelect} />
        )}

        {step === AppStep.DATA_ENTRY && (
          <StepDataEntry targetType={targetType} onSubmit={handleDataSubmit} />
        )}

        {step === AppStep.PROTOCOL && (
          <LoadingScreen phase="protocol" targetType={targetType} targetName={formData.targetName} />
        )}

        {step === AppStep.PROFILE_FOUND && (
          <StepProfileFound targetPhone={formData.targetPhone} photoUrl={profilePhoto} />
        )}

        {step === AppStep.ANALYSIS && (
          <LoadingScreen phase="analysis" targetType={targetType} targetName={formData.targetName} />
        )}

        {step === AppStep.VSL && (
          <VSLPage targetType={targetType} />
        )}
      </main>

      {step !== AppStep.VSL && <Footer />}
    </div>
  );
};

export default App;

